List<String> lines = Files.readAllLines(Path.of("hotels.csv"), StandardCharsets.UTF_8);
if (lines.isEmpty()) {
    return;   // nothing to read
}

String headerLine = lines.get(0);
// After readAllLines the BOM is one char, not three bytes.
if (headerLine.startsWith("\uFEFF")) {
    headerLine = headerLine.substring(1);
}
String[] header = headerLine.split(",", -1);

// Without the strip, header[0] is "\uFEFFhotel_id" and containsKey("hotel_id") is false.
System.out.println(header[0]);

static String sniffDelimiter(String headerLine) {
    // Semicolon present and comma absent means a semicolon file.
    if (headerLine.indexOf(';') >= 0 && headerLine.indexOf(',') < 0) {
        return ";";
    }
    // Same test for a tab separated export.
    if (headerLine.indexOf('\t') >= 0 && headerLine.indexOf(',') < 0) {
        return "\t";
    }
    return ",";
}

String delimiter = sniffDelimiter(headerLine);
// Pattern.quote keeps a delimiter such as "|" from acting as a regex operator.
String[] header = headerLine.split(Pattern.quote(delimiter), -1);
System.out.println(header.length + " columns, delimiter [" + delimiter + "]");

String[] header = lines.get(0).split(",", -1);

for (int i = 1; i < lines.size(); i++) {
    if (lines.get(i).isBlank()) {
        continue;   // blank line between blocks
    }
    String[] f = lines.get(i).split(",", -1);
    if (f.length != header.length) {
        // One message with the file line number beats an exception with a stack trace.
        System.out.println("line " + (i + 1) + ": expected " + header.length
                + " fields, found " + f.length);
        continue;
    }
    // Safe from here: every index in the header exists in the row.
    System.out.println(f[0] + " -> " + f[2]);
}

static Integer parseIntOrNull(String text) {
    String t = text.trim();
    if (t.isEmpty()) {
        return null;   // absent, not zero
    }
    try {
        return Integer.valueOf(t);
    } catch (NumberFormatException e) {
        return null;   // present but broken
    }
}

static LocalDate parseDateOrNull(String text) {
    String t = text.trim();
    if (t.isEmpty()) {
        return null;
    }
    try {
        return LocalDate.parse(t);   // strict: 2001-02-30 throws
    } catch (DateTimeParseException e) {
        return null;
    }
}

