static String pretty(String json) {
    StringBuilder out = new StringBuilder();
    int depth = 0;
    boolean inString = false;
    boolean escaped = false;

    for (int i = 0; i < json.length(); i++) {
        char c = json.charAt(i);
        if (inString) {
            out.append(c);
            if (escaped) {
                escaped = false;
            } else if (c == '\\') {
                escaped = true;
            } else if (c == '"') {
                inString = false;   // closing quote, structure resumes
            }
        } else if (c == '"') {
            inString = true;
            out.append(c);
        } else if (c == '{' || c == '[') {
            out.append(c).append('\n');
            depth++;
            out.append("  ".repeat(depth));
        } else if (c == '}' || c == ']') {
            out.append('\n');
            depth--;
            out.append("  ".repeat(Math.max(depth, 0)));
            out.append(c);
        } else if (c == ',') {
            out.append(",\n").append("  ".repeat(depth));
        } else if (c == ':') {
            out.append(": ");
        } else if (!Character.isWhitespace(c)) {
            out.append(c);   // whitespace outside strings is rebuilt by the indenter
        }
    }
    return out.toString();
}

System.out.println(pretty("{\"city\":\"Budapest\",\"tags\":[\"river\"]}"));

ObjectMapper mapper = new ObjectMapper()
        .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

record Hotel(int hotel_id, String name, String city, int stars) { }

String json = """
        [{"hotel_id": 10, "name": "Danube View", "city": "Budapest", "stars": 4,
          "owner_email": "owner@example.com"}]
        """;

List<Hotel> hotels = mapper.readValue(json, new TypeReference<List<Hotel>>() { });
for (Hotel h : hotels) {
    System.out.println(h.hotel_id() + " " + h.name());
}
// Without the TypeReference the list would hold LinkedHashMap and the cast would fail.

JsonNode root = mapper.readTree(json);
System.out.println(root.size());          // number of elements in the array

for (JsonNode node : root) {
    String name = node.path("name").asText("?");

    // path() returns a MissingNode when the key is absent; get() returns null.
    String owner = node.path("owner_email").asText("none");

    // An array of strings iterates the same way.
    StringBuilder tags = new StringBuilder();
    for (JsonNode tag : node.path("tags")) {
        if (tags.length() > 0) {
            tags.append('/');
        }
        tags.append(tag.asText());
    }
    System.out.println(name + " owner=" + owner + " tags=" + tags);
}

ObjectMapper mapper = new ObjectMapper();

List<Hotel> hotels = List.of(
        new Hotel(10, "Danube View", "Budapest"));

// Compact: one line, for a request body or a log entry.
String compact = mapper.writeValueAsString(hotels);

// Indented: for a file the examiner or a human opens.
String pretty = mapper.writerWithDefaultPrettyPrinter().writeValueAsString(hotels);
System.out.println(pretty);

// Straight to a file, UTF-8, no intermediate String.
Path out = Path.of("out", "hotels.json");
Files.createDirectories(out.getParent());
mapper.writerWithDefaultPrettyPrinter().writeValue(out.toFile(), hotels);
